#!/usr/bin/env python3
"""Editorial source-data construction for GY1969 records 209--228.

All statements are human/assistant editorial research, not output of symbolic
inference. Running this script serializes the reviewed record-level data.
The script and its log are retained to make every generated file reproducible.
"""
from pathlib import Path
import csv, json, collections, re

OUT=Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]; corrections=[]; sources=[]

def talk(record,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))

def item(record,pages,kind,title,notes,statement,reconstruction,cls,fate,refs=(),
         literal='correct with missing hypotheses',match='exact',verification='read the result',
         confidence='high',problem='',status='',speaker=None,development='none',worth=''):
    n=sum(x['record']==record for x in items)+1
    d=dict(id=f'1970-{record}.{n}',record=record,pages=pages,kind=kind,title=title,
           notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},
           fate=fate,present_status=status or 'As of November 2026, the reconstructed statement is established; no open problem is asserted.',
           literal_correctness=literal,publication_match=match,verification=verification,
           development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker:d['speaker']=speaker
    items.append(d)
    return d['id']

def problem(pid,title,statement,occurrences,status,refs):
    problems.append(dict(id=pid,title=title,statement=statement,occurrences=occurrences,
                         status=status,status_date='2026-11',refs=refs))

def correction(page,place,reads,should,evidence,applies='both',kind='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,
                            evidence=evidence,applies_to=applies,type=kind))

def source(key,url,support,locator,level='read the result'):
    sources.append(dict(key=key,url=url,opened=True,checked_date='2026-11-09',support=support,locator=locator,level=level))

def save():
    for name,obj in [('talks',talks),('items',items),('problems',problems),('sources',sources)]:
        (OUT/(name+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type'])
        w.writeheader();w.writerows(corrections)
    print(f'{len(talks)} talks; {len(items)} items; {len(problems)} problems; {len(corrections)} corrections; {len(sources)} source records (including any failed-access leads)')
    print('Classes:',dict(sorted(collections.Counter(x['class'] for x in items).items())))

talk(209,'1971-02-15','I. M. Gelfand','P000331','Differential geometry and Lie-algebra cohomology: announcement',r'The dated heading announces work with Kazhdan on differential-geometric notions and Lie-algebra cohomology. No theorem or construction is written under it. The holomorphic-vector-field discussion above the date belongs to the preceding session.',kind='heading')
talk(210,'1971-02-15','B. V. Fedosov','P000331','Bibliography for vector-field residue formulas',r'Fedosov supplies four references, including Bott\textquoteright s two 1967 papers and Baum--Bott\textquoteright s 1970 meromorphic-vector-field paper, and recalls the compact complex-manifold setting. Bernstein then develops the meromorphic version under his own heading.')
talk(211,'1971-02-15','I. N. Bernstein','P000331-P000332','Polar divisors and regularized Chern numbers',r'The polar divisor of a meromorphic vector field produces a degree-two class \(\rho\). The notes replace the Chern classes by the coefficients of \(c(TX)/(1-\rho)\) before applying a zero-residue formula. Isolated zero and nondegeneracy assumptions are largely shorthand.')
talk(212,'1971-02-15','B. V. Fedosov','P000332','Pontryagin numbers from zeros of a Killing field',r'A real analogue of Bott\textquoteright s formula uses a Killing vector field and the Pfaffian of its skew linearization. Compactness, nondegenerate isolated zeros, orientation, and characteristic-form normalization must be supplied.')
talk(213,'1971-02-22','V. I. Arnold','P000333-P000334','Versal deformations of matrices',r'Matrices depending on parameters are studied up to parameter-dependent conjugation. Jordan blocks explain singularities in the quotient, while transverse parameter families give versal deformations. Gelfand proposes a broader local picture for group actions and tensors, but the concluding conjectural language does not specify a mathematical category or equivalence.')
talk(214,'1971-03-01','A. M. Gabrielov','P000335','Griffiths on periods: bibliographical heading',r'The entire entry is a heading and a reference to Griffiths\textquoteright s Annals papers, volume 90, number 3. The substantive exposition resumes in records 220 and 222; it is not retrospectively placed under this heading.',kind='heading')
talk(215,'1971-03-01','I. N. Bernstein','P000335-P000336','Quasihomogeneous singularities and a torsion preprint',r'Bernstein reports Milnor--Orlik\textquoteright s formulas for the Milnor number and the monodromy divisor of an isolated quasihomogeneous hypersurface singularity. A brief comment connects polynomial-power distributions with cycles, and the page closes with news of the Ray--Singer preprint on analytic and combinatorial torsion.')
talk(216,'1971-03-01','I. M. Gelfand','P000337','Block determinants and positivity',r'Gelfand recalls the Schur-complement factorization and a positivity criterion. The same subject occurred in item 1964-17.2. The notebook conflates nonnegative and positive-definite inequalities, so both precise versions are separated in the commentary.')
talk(217,'1971-03-01','S. P. Novikov','P000337-P000339','Determinants of complexes and lens-space torsion',r'An acyclic based finite complex has an alternating determinant, independent of the auxiliary boundary splittings. Twisted cellular complexes of lens spaces illustrate Reidemeister torsion. A nontrivial character is essential: the untwisted universal-cover complex is not acyclic.')
talk(218,'1971-03-01','V. I. Arnold','P000339-P000340','Miniversal matrix families and centralizers',r'The exposition of record 213 continues with a categorical description of induced deformations, an explicit nine-parameter family, and the centralizer-dimension formula. Transversality supplies versality; the notebook\textquoteright s description as a final object is stronger than the actual property.')
talk(219,'1971-03-15','L. D. Faddeev','P000341-P000344','Inverse scattering and Hamiltonian KdV',r'The one-dimensional inverse-scattering solution of KdV is followed by its Hamiltonian structure and scattering action--angle variables, subsequently published by Zakharov and Faddeev. The final part concerns multidimensional scattering and a Volterra factorization of the scattering operator already announced by Faddeev in 1966. The notebook changes KdV normalizations without consistently changing all coefficients.')
talk(220,'1971-03-15','A. M. Gabrielov','P000344-P000345','Rational periods and tubes about a hypersurface',r'Following Griffiths, rational differential forms are integrated over cycles avoiding their polar hypersurface. Projective compactification and a tube construction explain which cycles are relevant. Record 222 continues the homological and pole-reduction argument.')
talk(221,'1971-03-15','V. I. Arnold','P000346','Real plane curves and the Gudkov congruence',r'Harnack and Petrovskii bounds lead to Gudkov\textquoteright s modulo-eight conjecture for maximal curves. Arnold reports the modulo-four result and links it to characteristic elements of integral intersection forms on a branched double cover. The stronger congruence was proved by Rokhlin in a note received in December 1971.')
talk(222,'1971-03-22','A. M. Gabrielov','P000347-P000349','The tube exact sequence and Griffiths reduction',r'The tube-map kernel is identified with the image of ambient projective homology. Homogeneous coordinates then give rational projective forms and a Jacobian-ideal formula reducing pole order. Two displayed formulas need explicit corrections: kernel means image of the intersection map, and the numerator degree depends on the pole order.')
talk(223,'1971-03-22','V. P. Palamodov','P000349','Characteristics of differential systems',r'Palamodov argues that differential consequences must be included before assigning a characteristic variety to a system. The first example is corrupted as a mathematical formula even though the transcription follows the scan. The underdetermined divergence equation illustrates the difference between analytic existence and unique determination by Cauchy data.')
talk(224,'1971-03-29','S. Rolewicz','P000350','Linear orbits and the hypercyclic weighted shift',r'Finite-dimensional orbit behavior is contrasted with the dense orbit of a multiple of the unilateral backward shift. The concatenation construction is sketched, with additional remarks on topological equivalence and algebraic operators unbounded in every norm.')
talk(225,'1971-03-29','V. I. Arnold','P000350-P000351','Unimodular integral forms and characteristic vectors',r'Arnold continues the arithmetic used for real curves: characteristic elements, the signature congruence modulo eight, and the classification of indefinite unimodular forms. Definite forms obey a finiteness theorem but are not classified merely by rank and signature. Serre\textquoteright s arithmetic text is recommended.')
talk(226,'1971-04-05','A. A. Kirillov','P000352-P000353','Sites, sheaves, and representations',r'Kirillov presents material attributed to Geronimus: coverings in a category, the sheaf condition, and cohomology. For a finite group the site of finite group-sets recovers ordinary representations. Geronimus\textquoteright s short 1971 announcement and detailed article identify the Lie-group site and its comparisons with classifying-space and differentiable cohomology. The notebook confuses general morphisms with the submersions used in covering families.')
talk(227,'1971-04-05','I. M. Gelfand','P000354-P000355','The elliptic-curve modularity conjecture',r'The \emph{Weil conjecture} here is modularity of elliptic curves over \(\mathbb Q\), expressed by a modular parametrization, local Euler factors, and integrals of a weight-two modular form. It is not the Weil conjectures for varieties over finite fields. The handwritten cubic exponent is retained rather than silently normalized, and the treatment of conductors explicitly starts with \(p\ne2,3\).')
talk(228,'1971-04-12','A. M. Perelomov','P000356-P000359','Theta functions, coherent lattices, and uncertainty',r'Integral symplectic lattices and quadratic refinements lead to theta-function identities and completeness of lattice coherent states. The critical-density deletion result was already published in Perelomov\textquoteright s February 1971 paper. A question about bounded centered position--momentum uncertainty for an orthogonal basis has a positive general answer; restrictions preserving a Gabor lattice change the answer. The final leaf P000360 is an adjacent out-of-scope record: Kirillov on 6 September 1971, not a continuation of this April session.')

item(209,'P000331','remark','Announcement of work with Kazhdan',r'The heading announces \ru{Некоторые понятия дифф. геометрии и их применение к вопросам} followed by an abbreviated reference to Lie-algebra cohomology.',r'Only the subject and joint authorship are recoverable. No particular formal-coordinate bundle, cochain map, or cohomology calculation is stated.',r'Identification with the later Gelfand--Kazhdan paper is bibliographical, not a reconstruction of an unwritten theorem.','F',r'The closely matching joint title appears in \citet[pp.~269--272]{gelfandkazhdan1971geometry}; the notes do not permit an exact result-level match.',['gelfandkazhdan1971geometry'],literal='not determinable',match='thematic only',verification='publisher metadata checked',confidence='medium',status='As of November 2026, the topic and subsequent publication are identified, but the announced mathematical content remains unrecoverable from this entry.')
item(210,'P000331','method','Bibliographical route from holomorphic to meromorphic residues',r'Fedosov lists Michigan Math. J. 14 (1967), 231--244; J. Differential Geom. 1 (1967), 311--330; a 1970 Matematika translation; and Baum--Bott, pp.~29--47 in the de Rham volume.',r'The first two entries are Bott\textquoteright s vector-field characteristic-number and holomorphic-residue papers. The fourth is Baum--Bott\textquoteright s meromorphic-vector-field extension. These are sources for, rather than new assertions beyond, the adjacent formulas.',r'Titles, authors, and full publication details are supplied by bibliographical matching. The unspecified Matematika entry is not assigned a separate result.','E',r'The titles and pagination are verified in the authors\textquoteright curated bibliographies \citep{bott1967vector,bott1967residue,baumbott1970zeroes}.',['bott1967vector','bott1967residue','baumbott1970zeroes'],literal='correct',verification='publisher metadata checked')
item(211,'P000331','construction','Polar divisor of a meromorphic vector field',r'The pole set is written as irreducible hypersurfaces \(Y_i\), with an effective cycle \(\sum\alpha_iY_i\). A local equation removes the pole of \(V\).',r'For a meromorphic section \(V\) of \(TX\) on a complex manifold, choose an effective Cartier divisor \(D=\sum m_iY_i\) clearing its poles. Then \(V\) is a holomorphic section of \(TX\otimes\mathcal O(D)\), or equivalently a morphism \(\mathcal O(-D)\to TX\). Set \(\rho=c_1(\mathcal O(D))\in H^2(X;\mathbb Z)\).',r'The divisor is a real codimension-two cycle; the notes\textquoteright wording \emph{two-dimensional cycles} confuses degree and dimension. Local multiplicities and the line-bundle formulation are made explicit.','E',r'This is the setup of the 1970 meromorphic residue theorem \citep[pp.~29--47]{baumbott1970zeroes}; its abstract explicitly uses a tangent field twisted by a line bundle.',['baumbott1970zeroes'],verification='publisher metadata checked')
item(211,'P000332','definition','Regularized Chern classes of the meromorphic field',r'\(a_1=c_1+\rho\), \(a_2=c_2+c_1\rho+\rho^2\), and \(a_i=c_i+c_{i-1}\rho+\cdots+\rho^i\).',r'These are the degree-\(2i\) components of \(c(TX-\mathcal O(-D))=c(TX)/(1-\rho)\). They are classes of a virtual bundle of rank \(n-1\), not the ordinary Chern classes of \(TX\otimes\mathcal O(D)\).',r'The virtual-bundle identification is editorial; it prevents replacing the notebook\textquoteright s actual formula with a different tensor-product formula.','E',r'Baum--Bott\textquoteright s meromorphic formulation is the prior source named in the notes \citep[pp.~29--47]{baumbott1970zeroes}. The algebraic identity is checked directly from the displayed notebook coefficients.',['baumbott1970zeroes'],literal='correct',verification='publisher metadata checked',confidence='medium')
item(211,'P000332','theorem','Residues for meromorphic one-dimensional foliations',r'The notes ask that the preceding holomorphic residue formula be applied using the regularized \(a_i\).',r'Let \(X\) be compact complex of dimension \(n\), and \(L=\mathcal O(-D)\to TX\) a holomorphic line-bundle morphism with isolated nondegenerate zeros. For an invariant polynomial \(\phi\) of degree \(n\), its characteristic number on \(TX-L\) is the sum of local residues. In a local frame, with derivative matrix \(A_p\), the nondegenerate residue is \(\phi(A_p)/\det A_p\). Rescaling the local frame cancels because both numerator and denominator have degree \(n\).',r'Compactness, isolated zeros of the extended morphism, and nondegeneracy are supplied. Zeros created on the polar divisor must also be included; counting only zeros away from poles need not give the characteristic number.','E',r'The named prior paper is \citet[pp.~29--47]{baumbott1970zeroes}; the accessible abstract confirms the twisted-field extension, but the full original theorem was not obtained. The exact hypotheses above are an explicit reconstruction, not a claim of full-text verification.',['baumbott1970zeroes'],match='partial',verification='publisher metadata checked',confidence='medium')
item(212,'P000332','definition','Killing field and skew linearization',r'The metric identity is \(([X,Y],Z)+(Y,[X,Z])=X(Y,Z)\); at a zero, the derivative \(\Theta_p\) is skew.',r'A smooth vector field \(X\) is Killing when \(\mathcal L_Xg=0\). At a zero \(p\), \(A_p=(\nabla X)_p\) is skew-adjoint on \(T_pM\), and a nondegenerate zero means \(\det A_p\ne0\).',r'The displayed identity is read as a formula for the Riemannian inner product, not a Lie-algebra bilinear form.','E',r'This is the infinitesimal-isometry framework used by \citet[pp.~173--193]{baumcheeger1969isometries}.',['baumcheeger1969isometries'],verification='publisher metadata checked')
item(212,'P000332','theorem','Real localization formula with a signed Pfaffian',r'For an oriented manifold of dimension \(4k\), the Pontryagin characteristic number is a sum of \(\psi(\Theta_p)/\operatorname{Pf}(\Theta_p)\).',r'For a closed oriented Riemannian \(4k\)-manifold and a Killing field with isolated nondegenerate zeros, an invariant polynomial representing a Pontryagin number localizes as \(\int_M\psi(R/(2\pi))=\sum_p\psi(A_p)/\operatorname{Pf}(A_p)\), with matching Chern--Weil conventions. The Pfaffian uses the given orientation; it is not an unsigned square root of the determinant.',r'Closedness and isolated nondegenerate zeros are essential. A consistent normalization is specified; numerator and denominator have the same total degree, so common \(2\pi\) factors cancel.','E',r'The prior infinitesimal-isometry result is \citet[pp.~173--193]{baumcheeger1969isometries}; Bott\textquoteright s 1967 characteristic-number work is also explicitly on the reading list \citep{bott1967vector}. Original result-level access was incomplete.',['baumcheeger1969isometries','bott1967vector'],verification='publisher metadata checked',confidence='medium')

item(213,'P000333','definition','Equivalence and induced matrix deformations',r'A matrix \(A(\lambda)\) depending on parameters is considered after changes of parameters and parameter-dependent similarity transformations.',r'A deformation of \(A_0\in\operatorname{Mat}_n(\mathbb C)\) is a smooth or holomorphic germ \(A:(\mathbb C^r,0)\to(\operatorname{Mat}_n,A_0)\). Another deformation is induced if \(B(\mu)=S(\mu)^{-1}A(\varphi(\mu))S(\mu)\), where \(\varphi(0)=0\) and \(S(0)\) centralizes \(A_0\) (one may require \(S(0)=I\)). Versality means every deformation is so induced in the chosen category.',r'The smooth and holomorphic categories are separated; the notes do not authorize a topological classification under arbitrary homeomorphisms.','A',r'Arnold\textquoteright s 1971 paper gives the parameter-dependent normal-form theory \citep[pp.~29--43]{arnold1971matrices}. The lecture precedes the journal issue; no earlier preprint date was established.',['arnold1971matrices'],verification='publisher metadata checked')
item(213,'P000333-P000334','method','Transverse slices as versal parameter families',r'Jordan normal forms organize the possible matrices, but smooth parameter-dependent normal forms require extra entries near repeated eigenvalues.',r'At \(A_0\), the conjugacy orbit has tangent space \([A_0,\operatorname{Mat}_n]\). If \(V\) is a linear complement, then \(A_0+V\) is miniversal locally: the map \((S,v)\mapsto S^{-1}(A_0+v)S\) is a submersion at \((I,0)\). Its parameter dimension is \(\dim\ker\operatorname{ad}_{A_0}\).',r'The complement and submersion argument are a modern precise reconstruction. Jordan canonical form chosen independently at each parameter does not itself prove smooth versality.','A',r'The normal-form framework matches \citet[pp.~29--43]{arnold1971matrices}; the detailed continuation and parameter count occur in record 218.',['arnold1971matrices'],verification='publisher metadata checked')
item(213,'P000334','conjecture','Gelfand’s proposed local model for general group actions',r'Gelfand discusses high-order tensors and proposes that locally one has a nonsingular fibration plus a remaining adjoint/Jordan-form problem.',r'The group, action, locality, topology, allowable equivalence, and meaning of the remaining adjoint problem are not fixed. This is a research heuristic, not a quantified slice theorem.',r'No universal theorem is supplied: a modern slice result for a specified proper or reductive action would add substantial assumptions not present here.','F',r'Searches under Arnold\textquoteright s matrix paper and the Gelfand--Kazhdan bibliography give related normal-form/cohomology topics, not an exact publication of this general conjecture \citep{arnold1971matrices,gelfandkazhdan1971geometry}.',['arnold1971matrices','gelfandkazhdan1971geometry'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',speaker='I. M. Gelfand',status='As of November 2026, no definite proposition is recoverable; no open problem or absence-of-development claim is entered.')
item(213,'P000334','remark','Invariant distributions as motivation',r'The closing remarks mention invariant generalized functions together with the geometry of orbits.',r'No distribution space, invariance equation, support condition, or claimed classification is given.',r'This occurrence is retained separately because it suggests an analytic application, but no theorem about invariant distributions is inferred.','F',r'The matrix-deformation publication is only a thematic context \citep{arnold1971matrices}; the remark cannot be matched to a result.',['arnold1971matrices'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',status='As of November 2026, this remains an unidentified remark, not a documented unsolved problem.')
item(214,'P000335','remark','Reference to Griffiths’s rational-period papers',r'The heading gives Griffiths, Annals of Mathematics 90, no.~3.',r'The bibliographical reference is to the two 1969 papers, pp.~460--495 and 496--541. No independent assertion accompanies this entry.',r'The title and page ranges are supplied from the author\textquoteright s publication list; the later Gabrielov exposition has its own occurrences.','E',r'The author\textquoteright s bibliography verifies both papers \citep{griffiths1969periods1,griffiths1969periods2}. Its attached PDF is a different 1968 paper and was not treated as the 1969 full text.',['griffiths1969periods1','griffiths1969periods2'],literal='correct',verification='publisher metadata checked')

item(215,'P000335','definition','Weighted homogeneity and the isolated singularity',r'For the weights \(w_i\), monomials satisfy \(\sum i_j/w_j=1\); \(f=0\) has an isolated critical point at the origin.',r'Let \(f\in\mathbb C[z_1,\ldots,z_m]\) be weighted homogeneous of weighted degree one with positive rational coordinate weights \(q_i=1/w_i\), and suppose \(\nabla f\) vanishes only at \(0\). The Milnor fibre has reduced homology concentrated in degree \(m-1\); its rank is the Milnor number \(\mu\).',r'The notebook\textquoteright s \(w_i\) are reciprocals of a widespread modern weight convention. Reduced homology is required also for \(m=1\).','E',r'This is the setting of \citet[pp.~385--393]{milnororlik1970weighted}; the modern formulation is checked in \citet[definition preceding Theorem~1.5]{hertlingmase2022weights}.',['milnororlik1970weighted','hertlingmase2022weights'])
item(215,'P000335-P000336','theorem','Milnor number of a weighted homogeneous hypersurface',r'\(\mu=\prod_i(w_i-1)\); the diagonal example is \(z_1^{a_1}+\cdots+z_m^{a_m}\).',r'Under the isolated-critical-point hypothesis, \(\mu=\dim_{\mathbb C}\mathbb C[z]/(\partial f)=\prod_i(q_i^{-1}-1)\). For the Brieskorn polynomial with integers \(a_i\ge2\), this is \(\prod_i(a_i-1)\).',r'The finite-dimensional Jacobian algebra is supplied as the precise meaning of multiplicity; arbitrary positive rational weights without an isolated singularity do not suffice.','E',r'The formula was published before the talk in \citet{milnororlik1970weighted}; its Jacobian-algebra interpretation is checked against \citet[Theorem~6.4(b)]{hertlingmase2022weights}.',['milnororlik1970weighted','hertlingmase2022weights'])
item(215,'P000336','construction','The group-ring divisor calculation for monodromy',r'In \(\mathbb Q[\mathbb C^*]\), \(E_k=k^{-1}\sum_{\zeta^k=1}[\zeta]\) is an idempotent. For reduced \(w_i=u_i/v_i\), the monodromy divisor is \(\prod_i(w_iE_{u_i}-1)\).',r'Write \(\Lambda_d=\sum_{\zeta^d=1}[\zeta]\), with multiplication induced by multiplication of complex numbers. Then \(\Lambda_a\Lambda_b=\gcd(a,b)\Lambda_{\operatorname{lcm}(a,b)}\), and \(\operatorname{div}\det(tI-h_*)=\prod_i(\Lambda_{u_i}/v_i-[1])\). For an isolated weighted homogeneous singularity the final coefficients are nonnegative integers.',r'The symbol \(1\) denotes the identity group-ring element \([1]\). Rational intermediate coefficients do not mean the characteristic polynomial has fractional multiplicities.','E',r'The monodromy formula is exactly the Milnor--Orlik theorem, explicitly restated in \citet[Theorem~6.4(a)]{hertlingmase2022weights}; the original paper is \citet{milnororlik1970weighted}.',['milnororlik1970weighted','hertlingmase2022weights'])
item(215,'P000336','remark','Polynomial-power distributions and cycles',r'Bernstein connects poles or residues of \(P^\lambda\) with cycles and their transformations.',r'The note does not specify the polynomial, real or complex distribution, integration cycle, pole, or claimed relation. Meromorphic continuation and monodromy are distinguishable questions; neither a precise residue formula nor a monodromy eigenvalue theorem is recorded.',r'No theorem is reconstructed from the general association.','F',r'Searches for Bernstein, polynomial powers, residues, and monodromy locate the later Bernstein--Sato theory, but do not identify this unquantified remark with one exact result. The preceding Milnor--Orlik formulas supply context only \citep{milnororlik1970weighted}.',['milnororlik1970weighted'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',status='As of November 2026, the general research direction is recognizable, but this occurrence does not define a new question.')
item(215,'P000336','construction','The Ray–Singer preprint and analytic torsion',r'The notebook mentions a preprint by Singer \emph{and someone else} on an analytic expression for torsion.',r'For a closed Riemannian manifold \(M\) and a unitary flat bundle \(E\), the positive Hodge-Laplacian spectrum defines \(\zeta_q(s)\). Analytic torsion is \(T(M,E)=\exp\{\frac12\sum_q(-1)^q q\zeta_q^{\prime}(0)\}\), with a stated torsion convention. For nonacyclic \(E\), comparison uses the corresponding determinant-line metric or compatible cohomology bases.',r'Daniel B. Ray is the missing coauthor. Zeta regularization is not an ordinary convergent product of all eigenvalues; zero modes are omitted.','E',r'The preprint was circulating by this 1 March 1971 report; the paper appeared later in 1971 as \citet{raysinger1971torsion}. This identifies the construction, not a proof then available of the general equality.',['raysinger1971torsion'],match='partial',verification='publisher metadata checked',confidence='medium')
item(215,'P000336','question','Equality of analytic and Reidemeister torsion',r'The preprint is described as expressing combinatorial torsion analytically; the status of a general equality is not separated from the proposal.',r'For a closed smooth manifold and an acyclic unitary flat bundle, does Ray--Singer analytic torsion equal the corresponding positive Reidemeister torsion? With cohomology present the comparison is one of metrics on the determinant line.',r'The equality is identified as the Ray--Singer conjecture; it must not be reported as a theorem already proved by the 1971 preprint.','B',r'Cheeger announced a proof in 1977 \citep[p.~2651, abstract]{cheeger1977torsion}; M\"uller\textquoteright s independent full paper appeared in 1978 \citep{muller1978torsion}.',['raysinger1971torsion','cheeger1977torsion','muller1978torsion'],literal='not determinable',match='partial',verification='indirect',confidence='medium',problem='GP-1970-50',status='As of November 2026, the unitary comparison is the established Cheeger--M\"uller theorem. The notes do not formulate later nonunitary anomaly questions.')
problem('GP-1970-50','Analytic and combinatorial torsion',r'Equality of Ray--Singer and Reidemeister torsion for closed manifolds with an acyclic unitary flat bundle, with the determinant-line interpretation when cohomology is present.',['1970-215.6'],r'As of November 2026, solved: Cheeger\textquoteright s 1977 announcement and M\"uller\textquoteright s 1978 proof establish the unitary comparison. The 1971 report is a preprint occurrence, not its solution.',['raysinger1971torsion','cheeger1977torsion','muller1978torsion'])

item(216,'P000337','theorem','Schur determinant factorization',r'For a block matrix, \(\det\begin{pmatrix}A&B\\C&D\end{pmatrix}=\det D\det(A-BD^{-1}C)\).',r'For square \(A,D\) over \(\mathbb C\), conformable off-diagonal blocks, and invertible \(D\), the stated determinant identity follows from block Gaussian elimination.',r'Finite dimensions and invertibility are made explicit; no infinite-dimensional regularized determinant is meant. The same elementary identity already appears as 1964-17.2.','E',r'This is the classical Schur-complement identity; the prior occurrence 1964-17.2 is reused as provenance. A modern reference is \citet[Chapter~1]{zhang2005schur}.',['zhang2005schur'],verification='publisher metadata checked')
item(216,'P000337','theorem','Positivity through the Schur complement',r'The notebook uses \(D\ge0\) and \(A-BD^{-1}C\ge0\) while concluding positive definiteness.',r'If \(M=\begin{pmatrix}A&B\\B^*&D\end{pmatrix}\) is Hermitian and \(D>0\), then \(M>0\) iff \(A-BD^{-1}B^*>0\), and \(M\ge0\) iff the latter Schur complement is \(\ge0\). If \(D\) is singular, the inverse formula must be replaced by a pseudoinverse together with \(\operatorname{ran}B^*\subseteq\operatorname{ran}D\).',r'Hermitian symmetry, strict versus weak positivity, and invertibility are supplied. These are corrections of the mathematical shorthand, not new assumptions silently attributed to the speaker.','E',r'The standard criterion is summarized in \citet[Chapter~1]{zhang2005schur}; the strict/weak distinction follows directly from the block congruence.',['zhang2005schur'],literal='false as written',verification='publisher metadata checked')

item(217,'P000337-P000338','definition','Determinant of an exact based complex',r'Novikov assigns a determinant to \(0\to E_0\to\cdots\to E_n\to0\) by choosing bases in images and lifting them to neighboring terms.',r'For a finite acyclic complex of finite-dimensional vector spaces over a field, fixed bases \(c_i\), boundary bases \(b_i\), and lifts of \(b_{i-1}\), torsion is the alternating product of the transition determinants \([b_i\widetilde b_{i-1}/c_i]^{(-1)^{i+1}}\), up to the explicitly chosen reciprocal/sign convention.',r'The bases in the complex itself are part of the data. Independence concerns auxiliary boundary bases and lifts, not arbitrary changes of all \(c_i\).','E',r'The algebraic construction and its change-of-basis rules precede the lecture; see \citet[\S3]{milnor1966torsion}.',['milnor1966torsion'])
item(217,'P000338','claim','Cancellation of auxiliary determinants',r'The alternating product is said not to depend on the arbitrary intermediate choices.',r'Changing a boundary basis contributes equal determinants in adjacent degrees with opposite exponents; changing its lift gives a block-unitriangular change. Therefore torsion is independent of these choices. Changing \(c_i\) multiplies it by the corresponding alternating determinant.',r'The elementary cancellation argument is expanded to specify precisely which basis-independence is true.','E',r'This is the standard based-complex torsion invariance \citep[\S3]{milnor1966torsion}.',['milnor1966torsion'])
item(217,'P000338-P000339','construction','Twisted cellular complex of a lens space',r'The lens-space complex has differentials \(1-\xi\), \(1+\xi+\cdots+\xi^{p-1}\), and \(1-\xi^\beta\).',r'For \(L(p,q)\), with \(p>1\), \(\gcd(p,q)=1\), and a nontrivial complex character taking a generator to \(\xi\), the twisted cellular chain complex has one one-dimensional term in degrees zero through three. Up to units/signs and the chosen generator, its maps are \(\xi-1,0,\xi^\beta-1\), with \(q\beta\equiv1\pmod p\). Both nonzero maps are invertible, so the twisted complex is acyclic.',r'The character is nontrivial and \(\xi\) need not be primitive provided \(\xi^p=1\); coprimality ensures \(\xi^\beta\ne1\). The universal-cover complex before twisting is not acyclic.','E',r'The classical lens-space example and the role of a character are treated in \citet[\S12]{milnor1966torsion}.',['milnor1966torsion'])
item(217,'P000339','claim','Lens-space determinant and the torsion convention',r'The written answer is \((1-\xi)(1-\xi^\beta)\).',r'With Novikov\textquoteright s alternating determinant convention one may obtain this product; with the usual chain-torsion convention \(\tau(L(p,q),\xi)\) is its reciprocal, modulo the units caused by cell lifts and orientations. The invariant must be quoted with its convention.',r'The notebook is not declared wrong merely because another convention inverts torsion. Its product is distinguished from an unconditional equality of canonically normalized complex numbers.','E',r'The reciprocal convention and unit ambiguity are explicit in the lens-space torsion calculation \citep[\S12]{milnor1966torsion}.',['milnor1966torsion'],literal='correct with missing hypotheses')

item(218,'P000339','definition','Versality is not a categorical final object',r'A deformation inducing all nearby deformations is described as a final object.',r'Versality requires existence of inducing parameter maps and conjugacies, not their uniqueness. Miniversality additionally minimizes the tangent parameter dimension. Nontrivial stabilizers generally obstruct the claimed final-object universal property.',r'The distinction between a versal object and a universal object is an editorial correction. It continues item 1970-213.1.','A',r'Arnold\textquoteright s matrix-deformation framework is the precise match \citep[pp.~29--43]{arnold1971matrices}; metadata and abstract were checked, not the complete proof.',['arnold1971matrices'],literal='false as written',verification='publisher metadata checked')
item(218,'P000339-P000340','construction','Nine parameters for Jordan blocks of sizes three and two',r'A five-by-five Jordan matrix with a common eigenvalue and blocks of lengths three and two is supplied with nine starred perturbation entries.',r'For \(A_0=J_3(\lambda)\oplus J_2(\lambda)\), the centralizer dimension is \(3+2+2+2=9\). A complement to \([A_0,\operatorname{Mat}_5]\) therefore yields a nine-parameter miniversal deformation. A particular star pattern is valid only if its coordinate subspace is such a complement.',r'The exact count is verified algebraically; the drawn placement of stars is not promoted into a uniquely determined normal form.','A',r'This is a concrete instance of \citet{arnold1971matrices}, illustrated by the notebook itself.',['arnold1971matrices'],verification='publisher metadata checked')
item(218,'P000340','theorem','Centralizer codimension and the dimension of a miniversal base',r'For Jordan blocks, the parameter count is \(n_1+3n_2+5n_3+\cdots\), summed over eigenvalues.',r'If the Jordan-block sizes for eigenvalue \(\lambda\) are \(n_{\lambda,1}\ge n_{\lambda,2}\ge\cdots\), then \(\dim Z(A)=\sum_\lambda\sum_{i,j}\min(n_{\lambda,i},n_{\lambda,j})=\sum_\lambda\sum_i(2i-1)n_{\lambda,i}\). This is the codimension of the conjugacy orbit and the dimension of a miniversal base.',r'The ordering of block sizes and separate summation over distinct eigenvalues are supplied.','A',r'The formula and transverse-family interpretation are the theory announced in \citet{arnold1971matrices}; the centralizer count itself is elementary Jordan-module algebra.',['arnold1971matrices'],verification='publisher metadata checked')

item(219,'P000341','method','KdV through an evolving Schrödinger operator',r'The notes write \(u_t+2u_{xxx}+6uu_x=0\), then associate \(-\partial_x^2+u\) to the initial potential.',r'For real Schwartz initial data, one standard normalization is \(u_t-6uu_x+u_{xxx}=0\) with \(L=-\partial_x^2+u\). Inverse scattering evolves the reflection coefficient by a cubic phase, keeps the negative eigenvalues fixed, and evolves their norming constants exponentially; inverse reconstruction gives the KdV solution.',r'The standard normalization is stated separately. The literal coefficients on P000341 do not agree with the Hamiltonian displayed on P000342; changing signs or rescaling must be done consistently.','E',r'The inverse-scattering method predates the talk; \citet[Introduction, equations (1)--(5)]{zakharovfaddeev1971kdv} explicitly reviews the earlier Gardner--Greene--Kruskal--Miura method.',['zakharovfaddeev1971kdv'],match='partial')
item(219,'P000341','definition','Reflection, transmission, and complete scattering data',r'The scattering solution behaves as \(e^{ikx}+a(k)e^{-ikx}\) at the left and \(b(k)e^{ikx}\) at the right, with \(|a|^2+|b|^2=1\).',r'For real \(u\) with \(\int(1+|x|)|u(x)|\,dx<\infty\), real \(k\ne0\) defines reflection \(r(k)\) and transmission \(t(k)\) coefficients with \(|r|^2+|t|^2=1\). To reconstruct a potential with bound states, reflection data must be supplemented by the negative eigenvalues and positive norming constants.',r'The notebook\textquoteright s \(a,b\) are reflected/transmitted amplitudes, whereas the later paper uses different letters. The discrete spectrum alone does not supply the norming constants.','E',r'The full data and inverse problem are stated in \citet[Introduction and \S1]{zakharovfaddeev1971kdv}.',['zakharovfaddeev1971kdv'])
item(219,'P000341','claim','Reflectionless potentials and solitons',r'When the reflected wave vanishes, one obtains solitons; the discrete spectrum remains relevant.',r'A real rapidly decaying reflectionless potential with finitely many simple negative eigenvalues and their norming constants produces a finite soliton solution under KdV evolution. With no bound states and zero reflection the potential is zero.',r'Reflectionless does not mean absence of scattering data: the eigenvalues and norming constants encode the solitons.','E',r'The scattering evolution and discrete variables are reviewed in \citet[Introduction, equations (4)--(5)]{zakharovfaddeev1971kdv}.',['zakharovfaddeev1971kdv'])
item(219,'P000341-P000342','claim','Conservation laws and the absence of shock formation',r'The margin associates infinitely many first integrals with the observation that shock waves do not arise.',r'For a smooth decaying KdV solution, integrations by parts give conserved local integrals, beginning with \(\int u\), \(\int u^2\), and, in the stated normalization, \(\int(u^3+\tfrac12u_x^2)\). Smooth real Schwartz data yield global smooth solutions in this integrable setting. The mere existence of many formal integrals is not by itself a proof of regularity.',r'The qualitative observation is separated from the invalid general implication that an unspecified collection of first integrals rules out singularities.','E',r'The established KdV integrals are listed in \citet[equation (2) and \S3]{zakharovfaddeev1971kdv}; the marginal explanatory claim is stronger than what that list alone proves.',['zakharovfaddeev1971kdv'],match='partial',confidence='medium')
item(219,'P000342','construction','Gardner’s Poisson bracket and a symplectic leaf',r'A double-integral skew form on variations \(\delta u\) is written, and the Hamiltonian is displayed as \(Q=\int(u^3+u_x^2)\,dx\).',r'The Hamiltonian operator \(J=\partial_x\) defines \(\{F,G\}=\int(\delta F/\delta u)\partial_x(\delta G/\delta u)\,dx\). On real Schwartz variations of zero integral, its inverse is \(\partial_x^{-1}v(x)=\frac12\int\operatorname{sgn}(x-y)v(y)\,dy\), giving a weak symplectic form. With \(H=\int(u^3+\tfrac12u_x^2)\,dx\), one obtains \(u_t=6uu_x-u_{xxx}\).',r'The fixed-mass leaf, skew inverse, and coefficient \(1/2\) specify a consistent convention. The literal notebook Hamiltonian yields \(6uu_x-2u_{xxx}\), not its earlier displayed equation.','E',r'The paper credits the bracket to Gardner and records the consistent Hamiltonian \citep[equations (6)--(7)]{zakharovfaddeev1971kdv}.',['zakharovfaddeev1971kdv'],literal='false as written',match='partial')
item(219,'P000342-P000343','method','Trace identities and scattering expressions for local integrals',r'The local integrals are expressed by moments of \(\log(1-|a|^2)\); the displayed expression for \(Q\) contains a \(k^4\) integral.',r'For real Schwartz potentials, the high-energy expansion of the transmission coefficient gives a hierarchy of trace identities: each appropriate local KdV integral is a fixed multiple of a moment of \(\log(1-|r(k)|^2)\) plus a finite sum of powers of the bound-state parameters. The constants depend on the KdV and scattering conventions.',r'The notebook\textquoteright s schematic integral is not a complete equality when eigenvalues occur. No unchecked numerical coefficient is inserted into that display.','A',r'The precise hierarchy and discrete terms appear in \citet[\S3, equations (25)--(30)]{zakharovfaddeev1971kdv}, received 14 June 1971.',['zakharovfaddeev1971kdv'],match='partial')
item(219,'P000343','construction','Canonical scattering coordinates',r'The skew form is rewritten using \(k\,\delta\log(1-|a|^2)\) and \(\delta\arg a\), with additional terms when eigenvalues exist.',r'In the published scattering convention \(r=b/a\), canonical variables include \(P(k)=-(k/\pi)\log(1-|r(k)|^2)\) and \(Q(k)=\arg b(k)\), together with bound-state action--angle pairs. On charts where the phases are defined, the symplectic form is the continuous canonical integral plus the discrete sum. Phase variables are singular at zeros of the corresponding coefficient.',r'The notebook reflection coefficient is not automatically the paper\textquoteright s \(b\); replacing \(\arg b\) by \(\arg r\) without the induced corrections is unjustified. The paper explicitly calls its calculations formal derivations rather than a complete analytic manifold construction.','A',r'This is the central new result of \citet[\S2, equations (22)--(24)]{zakharovfaddeev1971kdv}; the paper\textquoteright s methodological qualification is on p.~282.',['zakharovfaddeev1971kdv'],match='partial')
item(219,'P000343','definition','Three-dimensional scattering amplitude and the unitary operator',r'The asymptotic wave is \(e^{i\mathbf k\cdot x}+r^{-1}e^{ikr}f(k;\alpha,\beta)+o(r^{-1})\); \(f\) has five variables, and the notes write \(S(k)=I+f\), calling it unitary.',r'For a real sufficiently regular short-range potential in \(\mathbb R^3\), positive energy \(k^2\) and incident/outgoing directions \(\alpha,\beta\in S^2\) define the amplitude. The on-shell scattering operator on \(L^2(S^2)\), with its normalization factor and identity term, is unitary. The amplitude kernel alone is not a unitary operator.',r'The factor relating the amplitude integral operator to \(S(k)-I\) is convention dependent. The dimensional count is one energy variable and two variables for each direction.','E',r'The amplitude/operator distinction is explicit in \citet[p.~70, equations (5)--(8)]{faddeev1966factorization}.',['faddeev1966factorization'],literal='false as written',match='partial')
item(219,'P000343-P000344','method','Volterra factorization of the multidimensional scattering operator',r'The notes factor \(S(k)\) by \(Q_\gamma^{\pm}\), with kernels supported on one side of \((\alpha-\beta)\cdot\gamma=0\), and mention analytic continuation of diagonal data.',r'Faddeev\textquoteright s factorization uses modified Green functions and a fixed direction \(\gamma\). Provided the corresponding Fredholm equation is uniquely solvable, the resulting factors are triangular with respect to the angular order and recover \(S\); their diagonal data have the specified complex-direction continuation. The 1966 note assumes unique solvability and explicitly proves it only in a sufficiently small-potential regime.',r'The notebook signs and factor order depend on incoming/outgoing conventions. The uniqueness hypothesis is material; the construction is not an unconditional global inverse theorem for all decaying potentials.','E',r'The precise prior source is \citet[pp.~71--72, equations (10)--(13)]{faddeev1966factorization}, received 3 June 1965 and published in 1966.',['faddeev1966factorization'],match='partial')
item(219,'P000344','remark','The discrete-spectrum obstruction in the inverse problem',r'The Green function and factorization had been written down earlier, but \ru{Обратной задачи не было из-за дискретного спектра}.',r'This is a historical report about the method\textquoteright s unresolved analytic continuation and exceptional parameters. It does not specify a modern inverse-data problem, a uniqueness class, or a claimed obstruction for every potential.',r'It is not converted into a present-day open inverse-scattering conjecture.','F',r'The earlier paper explicitly left singularities of the continued modified solutions uncontrolled \citep[p.~72]{faddeev1966factorization}; the notebook does not identify a stronger exact question.',['faddeev1966factorization'],literal='not determinable',match='partial',confidence='medium',status='As of November 2026, the historical limitation is identifiable, but no definite surviving open problem follows from this sentence.')

item(220,'P000344','definition','Periods of rational differential forms',r'\(\omega=P(z)Q(z)^{-1}dz_1\wedge\cdots\wedge dz_n\), \(V=\{Q=0\}\), and \(\int_\Gamma\omega\) for \(n\)-cycles in the complement.',r'A closed rational top form on \(U=\mathbb C^n\setminus V\) pairs with \(H_n(U;\mathbb Z)\) by integration. After projective compactification all polar components, including a possible hyperplane at infinity, must be included in the divisor.',r'Closedness of a holomorphic top form is automatic on \(U\); a projective denominator must account for infinity rather than just the affine zero set.','E',r'The bibliography identifies \citet[Part~I]{griffiths1969periods1} as the prior source; the exact subject is stated in the notebook itself.',['griffiths1969periods1'],verification='publisher metadata checked')
item(220,'P000344','method','One-variable pole reduction and residues',r'Homology is generated by small loops around poles; higher-order poles are removed by subtracting exact differentials.',r'For a rational one-form on the punctured complex line, partial fractions split it into an exact rational differential plus a sum of simple-pole forms. Its period around a cycle is \(2\pi i\) times the integral linear combination of the enclosed residues.',r'The conventional \(2\pi i\) is restored; polynomial terms and all poles of order at least two contribute exact differentials.','E',r'This elementary prototype is the starting point of the rational-period exposition \citep{griffiths1969periods1}.',['griffiths1969periods1'],verification='publisher metadata checked')
item(220,'P000345','theorem','Middle-dimensional complement cycles vanish in projective space',r'\(H_n(\mathbb P^n\setminus V;\mathbb Z)\to H_n(\mathbb P^n;\mathbb Z)\) is zero; the even-dimensional case uses Bézout.',r'For a nonempty smooth hypersurface \(V\subset\mathbb P^n(\mathbb C)\) of degree \(q>0\), inclusion sends every middle-dimensional complement cycle to zero in projective homology. For odd \(n\), the target is zero. For \(n=2m\), intersecting with \(V\cap\mathbb P^{m+1}\), whose class is \(q[\mathbb P^m]\), forces its coefficient to vanish.',r'Positive degree and the torsion-free ambient group are explicit. The notebook\textquoteright s intersection proof is retained, rather than inferred from vanishing of a different cohomology group.','E',r'The projective-complement framework belongs to \citet{griffiths1969periods1}; the complete elementary argument is present in the notes and repeated in record 222.',['griffiths1969periods1'],verification='publisher metadata checked')
item(220,'P000345','construction','The tube map and its surjectivity in middle dimension',r'If \(\Gamma=\partial R\), take \(\gamma=R\cap V\); the circle tube \(\tau(\gamma)\) is homologous to \(\Gamma\).',r'For smooth \(V\), the oriented real rank-two normal bundle gives a tube homomorphism \(\tau:H_k(V;\mathbb Z)\to H_{k+1}(\mathbb P^n\setminus V;\mathbb Z)\). In degree \(k=n-1\), it is surjective by the preceding vanishing and the long exact sequence of the pair plus the Thom isomorphism.',r'The tube is the normal circle bundle over the cycle, not an arbitrary full neighborhood of the cycle in projective space. Chain orientations fix a possible conventional boundary sign.','E',r'This is the residue/tube construction underlying \citet{griffiths1969periods1}; record 222 supplies the exact sequence.',['griffiths1969periods1'],verification='publisher metadata checked')

item(221,'P000346','theorem','Harnack’s bound and real sextic configurations',r'For degree \(n=2k\), the number of ovals is at most \(g+1\), \(g=(n-1)(n-2)/2\). A separate note says degree six has “50 cases (Gudkov)” and sketches an eleven-oval arrangement.',r'A nonsingular real projective plane curve of even degree \(2k\) has at most \((2k-1)(k-1)+1\) connected components, all ovals. For degree six the maximum is eleven. The unqualified number fifty does not specify whether empty curves, isotopy schemes, or a partial classification are counted.',r'The numerical shorthand is not substituted for the number of all real schemes. The maximal-oval illustration is separated from that unresolved bibliographical count.','E',r'Arnold recalls Harnack and Gudkov\textquoteright s maximal sextics in \citet[\S1]{arnold1971ovals}. The exact interpretation of the notebook\textquoteright s “50” was not established.',['arnold1971ovals'],match='partial',confidence='medium')
item(221,'P000346','theorem','Petrovskii’s inequalities for even-degree plane curves',r'Writing \(p,m\) for ovals inside an even or odd number of other ovals gives \(|2(p-m)-1|\le3k^2-3k+1\).',r'For a nonsingular real projective plane curve of degree \(2k\), let \(p\) and \(m\) denote the numbers of even and odd ovals. Petrovskii\textquoteright s inequalities are equivalent to the displayed double inequality. Maximality is not needed for this bound.',r'“Positive oval” in the notes means even nesting parity, not orientation of the oval.','E',r'The prior inequalities are recalled in \citet[\S1]{arnold1971ovals}.',['arnold1971ovals'])
item(221,'P000346','conjecture','Gudkov’s congruence modulo eight',r'\(p-m\equiv k^2\pmod8\), following the discussion of curves with the maximal number of ovals.',r'For a nonsingular real projective \(M\)-curve of degree \(2k\), meaning it has \((2k-1)(k-1)+1\) components, one has \(p-m\equiv k^2\pmod8\). Without the \(M\)-curve hypothesis this is not the asserted theorem.',r'The maximality hypothesis is carried forward from the preceding paragraph and stated explicitly.','B',r'Rokhlin proved the exact congruence \citep[\S1]{rokhlin1972gudkov}; his note was received 29 December 1971 and published in 1972.',['rokhlin1972gudkov'],problem='GP-1970-51',status='As of November 2026, solved: this is the Gudkov--Rokhlin congruence, not an unresolved part of Hilbert\textquoteright s sixteenth problem.')
problem('GP-1970-51','Gudkov congruence for maximal real plane curves',r'For every nonsingular real projective \(M\)-curve of degree \(2k\), prove \(p-m\equiv k^2\pmod8\), with \(p,m\) the even/odd nesting counts.',['1970-221.3','1970-221.4'],r'As of November 2026, solved by Rokhlin: note received 29 December 1971, published 1972. Arnold\textquoteright s modulo-four result was the March 1971 intermediate step.',['arnold1971ovals','rokhlin1972gudkov'])
item(221,'P000346','theorem','Arnold–Varchenko’s modulo-four result',r'Arnold and Varchenko have proved \(p-m\equiv k^2\pmod4\) using quadratic forms.',r'For every nonsingular real projective \(M\)-curve of even degree \(2k\), the weaker congruence modulo four holds.',r'The published paper is authored by Arnold; its final discussion acknowledges Varchenko\textquoteright s initial argument and the development of the proof. Joint spoken attribution is not silently changed into joint publication authorship.','A',r'\citet[\S1 and final acknowledgments]{arnold1971ovals}, received 22 March 1971, publishes the result after the 15 March lecture.',['arnold1971ovals'],problem='GP-1970-51')
item(221,'P000346','claim','Characteristic squares are well defined modulo eight',r'For a characteristic \(u\), \((u+2x)^2=u^2+4(u,x)+4x^2\), and the two latter terms have matching parity.',r'For an integral symmetric bilinear form, if \((u,x)\equiv(x,x)\pmod2\) for every \(x\), then \((u+2x,u+2x)\equiv(u,u)\pmod8\). This calculation proves independence of the characteristic lift, not yet the equality with the signature.',r'The distinction between lift independence and the full van der Blij lemma prevents treating the displayed two-line calculation as a proof of both assertions.','E',r'The arithmetic tool is used in \citet{arnold1971ovals} and developed explicitly in record 225.',['arnold1971ovals'])
item(221,'P000346','method','Branched double covers connect real curves with intersection forms',r'The notes introduce \(z^2=f(x,y)\) and identify \(p-m\) with an Euler characteristic of a region of the real plane.',r'For a smooth real plane curve of even degree, the corresponding double cover of \(\mathbb P^2(\mathbb C)\), branched along its complexification, is a compact smooth complex surface. Real involutions and their fixed loci connect nesting data to its integral intersection form; characteristic-vector congruences then constrain the ovals.',r'The affine equation is compactified via the square root line bundle \(\mathcal O(k)\). Smoothness of the branch curve is required. The full topology is sourced, not claimed proved by the single notebook line.','A',r'This method is developed in \citet[\S\S2--8]{arnold1971ovals}; Rokhlin\textquoteright s stronger proof explicitly builds on it \citep[\S2]{rokhlin1972gudkov}.',['arnold1971ovals','rokhlin1972gudkov'])

item(222,'P000347-P000348','theorem','The integral tube exact sequence and the kernel question',r'The question \(\ker\tau=?\) is answered by \(H_{n+1}(\mathbb P^n)\to H_{n-1}(V)\to H_n(\mathbb P^n\setminus V)\to H_n(\mathbb P^n)\), followed by \(\ker\tau=H_{n+1}(\mathbb P^n)\).',r'For a smooth positive-degree hypersurface, the pair sequence and the oriented Thom isomorphism give an exact sequence over \(\mathbb Z\). Precisely, \(\ker\tau=\operatorname{im}(H_{n+1}(\mathbb P^n;\mathbb Z)\xrightarrow{\cap V}H_{n-1}(V;\mathbb Z))\). Thus the kernel is zero for even \(n\); for \(n=2m+1\), it is generated by the hyperplane-section class \([V\cap\mathbb P^{m+1}]\).',r'The image, not the domain as a literal subgroup equality, is the kernel. Exactness needs no passage modulo torsion. The ambient source is injective here because intersecting its image with a suitable power of the hyperplane class has nonzero degree.','E',r'This continues the tube construction in \citet{griffiths1969periods1}; the proof is reconstructed directly from the exact sequence already written in the notes.',['griffiths1969periods1'],literal='false as written',match='partial',verification='publisher metadata checked')
item(222,'P000348','method','A closed chain need not bound',r'The proof says \(\partial(T\gamma-R)=0\), hence \(T\gamma-R\) is a boundary.',r'The closed chain \(T\gamma-R\) defines an ambient homology class. Its intersection with \(V\) gives \(\gamma\), establishing membership in the image of the intersection map. There is no need, and in general no justification, to declare the ambient cycle a boundary.',r'This repairs the notebook\textquoteright s proof of exactness without changing the intended sequence.','E',r'The corrected chain argument is the ordinary proof of the pair/Thom exact sequence used in the rational-period construction \citep{griffiths1969periods1}.',['griffiths1969periods1'],literal='false as written',match='partial',verification='publisher metadata checked')
item(222,'P000348-P000349','construction','Homogeneous rational forms on projective space',r'\(\Omega=\sum(-1)^j\xi_j\,d\xi_0\wedge\cdots\widehat{d\xi_j}\cdots\wedge d\xi_n\), and \(P\Omega/Q^\ell\) descends to projective space.',r'If \(Q\) is homogeneous of degree \(q\) and \(P\) of degree \(\ell q-(n+1)\), then \(P\Omega/Q^\ell\) is horizontal and invariant under \(\mathbb C^*\), hence descends to a rational \(n\)-form on \(\mathbb P^n\). The formula \(\deg P=q-(n+1)\) applies only to a simple pole.',r'The pole-order factor \(\ell\) is missing from the final repeated degree formula on P000349; the earlier simple-pole formula on P000348 is correct.','E',r'This is the homogeneous form setup of \citet{griffiths1969periods1}; its degree is independently checked by scaling every coordinate.',['griffiths1969periods1'],literal='false as written',verification='publisher metadata checked')
item(222,'P000348','construction','Lower-degree basic forms by contraction with the Euler field',r'A more general alternating expression omits several \(d\xi_j\), and gives \(\deg B=\deg A+n+2-\ell\).',r'Let \(E=\sum\xi_i\partial_{\xi_i}\) and let \(\eta\) be a polynomial \((r+1)\)-form with homogeneous coefficients of degree \(a\). If \(B\) has degree \(a+r+1\), then \((\iota_E\eta)/B\) is a horizontal, scaling-invariant rational \(r\)-form. With \(r=n+1-\ell\), its degree condition is exactly the one in the notes.',r'The lengthy coordinate formula is interpreted as Euler contraction; this states a clean sufficient descent construction rather than an unchecked claim about every possible presentation.','E',r'The basic-form construction is part of the projective rational-form calculus cited as \citet{griffiths1969periods1}; scaling and \(\iota_E^2=0\) check the asserted property.',['griffiths1969periods1'],verification='publisher metadata checked')
item(222,'P000349','method','Griffiths reduction of a Jacobian numerator',r'Subtracting a coboundary yields \(P=\ell\sum A_jQ_j-Q\sum\partial_jA_j\).',r'For homogeneous \(Q\) of degree \(q\), \(\ell\ge1\), and homogeneous \(A_j\) of degree \(\ell q-n\), one has \(\frac{(\sum A_j\partial_jQ)\Omega}{Q^{\ell+1}}\equiv\frac{1}{\ell}\frac{(\sum\partial_jA_j)\Omega}{Q^\ell}\pmod{d\Omega^{n-1}(\mathbb P^n\setminus V)}\). Thus a numerator in the Jacobian ideal can be reduced by one pole order. A general numerator need not be in that ideal.',r'The two numerator degrees are distinguished, and the reduction is a cohomological congruence. Smoothness of \(V\) supports the subsequent finite Jacobian-ring description, although the displayed differentiation identity itself is algebraic.','E',r'This is the Griffiths pole-reduction mechanism, explicitly attributed in the notes to \citet{griffiths1969periods1}. Exact differentiation supplies the stated reconstruction; the original 1969 full text was not successfully retrieved.',['griffiths1969periods1'],verification='publisher metadata checked')

item(223,'P000349','method','Characteristics must use the differential module of the system',r'\ru{Надо выписать все следствия и с ними иметь дело}: all differential consequences must be included.',r'For an analytic linear differential system represented by a coherent module \(\mathcal M\) over the sheaf of differential operators, the characteristic support is the support of \(\operatorname{gr}\mathcal M\) for a good filtration. Taking only the symbols of an arbitrary initial generating list may omit principal symbols of differential consequences.',r'The coherent differential-module formulation is a modern reconstruction of the method, not terminology asserted to occur in the notes.','E',r'Palamodov\textquoteright s earlier work on differential operators in coherent analytic sheaves is a thematic source \citep{palamodov1968coherent}; the notebook does not identify a particular theorem from it.',['palamodov1968coherent'],match='thematic only',verification='publisher metadata checked',confidence='medium')
item(223,'P000349','claim','The displayed two-equation example is inconsistent',r'The system \(D_xu=f\), \((D_y+\lambda)u=g\) is followed by \(u=D_yg-D_xf\). The scan confirms the written \(\lambda\).',r'For constant \(\lambda\) and commuting partial derivatives, the actual compatibility is \(D_xg-D_yf=\lambda f\); it does not recover \(u\). An instructive different example would use \((D_y+x)u=g\), when \([D_x,D_y+x]u=u\) gives \(u=D_xg-(D_y+x)f\).',r'The latter system is explicitly an editorial illustration, not a proposed transcription of \(\lambda\). Both the notebook coefficient and its consequent fail to yield the claimed relation.','F',r'The general differential-consequence principle matches Palamodov\textquoteright s work \citep{palamodov1968coherent}; the intended specific example cannot be identified from the surviving formula.',['palamodov1968coherent'],literal='false as written',match='thematic only',verification='unresolved lead',confidence='high',status='As of November 2026, the literal countercalculation is decisive, but the author\textquoteright s intended example is not recoverable.')
item(223,'P000349','claim','Underdetermined divergence separates existence from uniqueness',r'For \(D_xu+D_yv=f\), Holmgren\textquoteright s theorem works in no direction, while Cauchy--Kovalevskaya works in every direction.',r'For analytic \(f\) in two variables, in any chosen nonzero normal direction one can solve for a normal derivative of one component after prescribing the other analytic component, giving local analytic solutions with compatible data. The equation alone does not uniquely determine both \(u\) and \(v\) from data on a hypersurface; hence a scalar Holmgren uniqueness conclusion cannot simply be transferred to this underdetermined system.',r'The statement is an existence/uniqueness contrast, not a contradiction between the two theorems. The arbitrary free component must be included.','E',r'The example illustrates the theory of systems underlying \citet{palamodov1968coherent}; no exact publication match for this pedagogical example was found.',['palamodov1968coherent'],match='thematic only',verification='publisher metadata checked',confidence='medium')

item(224,'P000350','claim','Finite-dimensional orbit alternatives',r'The limit behavior of \(x,Ax,A^2x,\ldots\) is described as zero, infinity, or a compact set excluding zero.',r'For a linear map on a finite-dimensional real or complex normed space and a fixed vector, either \(A^nx\to0\), or \(\|A^nx\|\to\infty\), or the orbit is bounded and its omega-limit set is nonempty compact and avoids zero. This follows by separating generalized eigenspaces with spectral radius below, equal to, or above one, and the polynomial growth of nontrivial Jordan chains.',r'“Limit points” means asymptotic behavior; infinity is not an ordinary point of the vector space, and the full orbit closure also contains initial transient points.','E',r'This contrast supplies the finite-dimensional background to Rolewicz\textquoteright s previously published example \citep{rolewicz1969orbits}.',['rolewicz1969orbits'],verification='publisher metadata checked')
item(224,'P000350','theorem','Rolewicz’s hypercyclic multiple of the backward shift',r'\(S(x_1,x_2,\ldots)=(x_2,x_3,\ldots)\), \(A=aS\), \(a>1\), can have an everywhere dense orbit on \(\ell^p\) or \(c^0\).',r'On \(\ell^p(\mathbb N)\), \(1\le p<\infty\), or \(c_0(\mathbb N)\), over \(\mathbb R\) or \(\mathbb C\), the bounded operator \(\lambda S\) is hypercyclic when \(|\lambda|>1\). The separability restriction excludes \(\ell^\infty\).',r'The index range and complex analogue \(|\lambda|>1\) are supplied. The Hilbert-space example is \(p=2\); no theorem about every Hilbert space dimension is intended.','E',r'\citet[pp.~17--22]{rolewicz1969orbits} appeared in 1969; the author\textquoteright s own institutional account identifies it as his hypercyclic example.',['rolewicz1969orbits'],verification='publisher metadata checked',problem='GP-1970-52')
problem('GP-1970-52','A bounded linear operator with a dense orbit',r'Does there exist a separable infinite-dimensional Banach space and a bounded linear operator on it with an orbit dense in the entire space? The notebook realizes this on sequence spaces by \(\lambda S\), \(|\lambda|>1\).',['1970-224.2','1970-224.3'],r'As of November 2026, the sequence-space existence question was already answered by Rolewicz in 1969. No universal assertion about all nonseparable or finite-dimensional spaces is included.',['rolewicz1969orbits'])
item(224,'P000350','construction','Concatenating small blocks to obtain a dense orbit',r'A list of finite rational blocks is concatenated after long zero gaps, with block \(j\) divided by a suitable power of \(a\).',r'Choose a dense sequence of finite-support vectors \(v_j\) with each target repeated, and increasing positions \(N_j\). Put the block \(\lambda^{-N_j}v_j\) at position \(N_j\), choosing later positions so that the tail after applying \((\lambda S)^{N_j}\) has norm below \(2^{-j}\) and all scaled block norms are summable. Then \((\lambda S)^{N_j}x-v_j\to0\), proving density.',r'The long gaps must control amplified later tails as well as place blocks without overlap; this quantitative choice fills the notebook\textquoteright s proof sketch. For complex spaces use rational real and imaginary parts.','E',r'The construction explains the prior result \citep{rolewicz1969orbits}; the detailed tail condition is an editorial unpacking of the notebook, not a new theorem.',['rolewicz1969orbits'],verification='publisher metadata checked',problem='GP-1970-52')
item(224,'P000350','definition','Topological conjugacy preserves a dense orbit',r'\(A=UBU^{-1}\) for a homeomorphism \(U\); orbit density is a topological property.',r'If \(U:X\to Y\) is a homeomorphism with \(UA=BU\), then \(U(\{A^nx\})=\{B^nU(x)\}\). Therefore hypercyclicity is invariant under topological conjugacy, even when \(U\) is nonlinear.',r'No claim of linear similarity follows from topological equivalence.','E',r'The invariant is an immediate consequence of the definition and contextualizes \citet{rolewicz1969orbits}.',['rolewicz1969orbits'],literal='correct',verification='publisher metadata checked')
item(224,'P000350','claim','An algebraic operator unbounded in every norm',r'One can construct an operator unbounded in every norm.',r'On the algebraic vector space of finite-support sequences, define \(Te_n=ne_n\). For every norm on this space, a bound \(\|Tx\|\le C\|x\|\) would imply \(n\le C\) for all \(n\), so no such bound exists.',r'The example is editorial and proves a natural literal existential reading. The notes give no ambient space, completeness requirement, or specific operator, so they do not identify this particular construction.','F',r'The sentence was searched together with Rolewicz\textquoteright s algebraic-operator and orbit work; no exact publication or intended ambient space was established. The institutional bibliography records \emph{Equations in linear spaces} (1968), but that broad title is not an exact match.',['rolewicz1969orbits'],literal='correct with missing hypotheses',match='none found',verification='unresolved lead',confidence='low',status='As of November 2026, the existential algebraic reading is elementary and true; the intended generality is unidentified, not an open problem.')

item(225,'P000350-P000351','definition','Unimodular lattices, parity, and characteristic elements',r'\(\varphi:\mathbb Z^n\times\mathbb Z^n\to\mathbb Z\) is unimodular when it identifies the lattice with its dual. Rank, signature, and types I/II are listed.',r'An integral symmetric nondegenerate form is unimodular when its determinant is \(\pm1\). It is even if \((x,x)\) is even for every \(x\), and odd otherwise. Because reduction modulo two is nondegenerate, the linear functional \(x\mapsto(x,x)\bmod2\) has a unique representing class \(u\in L/2L\), called characteristic.',r'Symmetry and nondegeneracy are supplied. “Type I” denotes odd and “type II” even; the characteristic vector is unique only modulo \(2L\).','E',r'The notebook\textquoteright s cited arithmetic text treats these forms in Chapter~V \citep{serre1970arithmetic}. Earlier lectures underlying the book date to 1962 and 1964.',['serre1970arithmetic'],verification='publisher metadata checked')
item(225,'P000351','theorem','Van der Blij’s characteristic-signature congruence',r'\(\varphi(u,u)\bmod8\) is independent of the lift and equals \(\operatorname{sgn}\varphi\bmod8\); a Fresnel integral is mentioned.',r'For an integral unimodular symmetric bilinear lattice and any characteristic vector \(u\), \((u,u)\equiv\sigma(L)\pmod8\). In particular, an even unimodular lattice has signature divisible by eight.',r'Unimodularity is needed for the signature assertion; the simpler lift-independence calculation is separately recorded in 1970-221.5. The mention of a Fresnel integral is a proof method, not a supplied analytic proof.','E',r'The classical arithmetic result is used explicitly by \citet{arnold1971ovals} and belongs to the unimodular-form treatment cited as \citet[Chapter~V]{serre1970arithmetic}.',['arnold1971ovals','serre1970arithmetic'])
item(225,'P000350-P000351','theorem','Classification of indefinite integral unimodular forms',r'Rank, signature, and parity are complete invariants in the indefinite case; odd forms diagonalize, and even forms use \(U\) and \(\Gamma_8\).',r'An odd indefinite unimodular lattice of signature \((p,q)\), \(p,q>0\), is \(I_{p,q}\). An even indefinite unimodular lattice exists exactly when \(p-q\equiv0\pmod8\) and is unique for that signature; it is an orthogonal sum of hyperbolic planes and copies of signed \(E_8\).',r'The sign of \(E_8\) is chosen to realize either signature. The indefinite hypothesis is indispensable; rank and signature alone do not distinguish parity.','E',r'The exposition points to \citet[Chapter~V]{serre1970arithmetic}; the publisher\textquoteright s description confirms this chapter\textquoteright s subject, but its full theorem text was not retrieved.',['serre1970arithmetic'],verification='publisher metadata checked')
item(225,'P000351','theorem','Finiteness in the positive-definite case',r'Positive-definite unimodular forms are finite in number in every dimension.',r'For each fixed rank \(n\), there are finitely many isometry classes of positive-definite integral unimodular lattices. This is finiteness of classes, not uniqueness or an explicit classification by rank and signature.',r'Equivalence means integral lattice isometry, and the determinant is fixed at one. Without fixing determinant the assertion would be false.','E',r'This is the definite reduction-theory counterpart of the Chapter~V discussion in \citet{serre1970arithmetic}.',['serre1970arithmetic'],verification='publisher metadata checked')
item(225,'P000351','remark','What kind of stabilization erases parity?',r'The final line says that stably only rank and signature remain, followed by “Dear Misha you are wrong.”',r'If stabilization means adding only hyperbolic even planes \(U\), parity remains invariant, so rank and signature do not suffice. If both forms may be augmented by the same odd indefinite plane \(\langle1\rangle\oplus\langle-1\rangle\), then forms of equal rank and signature become odd indefinite and hence isometric by the classification theorem.',r'The notes do not identify the permitted stabilizations or the target of the handwritten disagreement. The two precise readings are kept separate.','F',r'The arithmetic classification in \citet[Chapter~V]{serre1970arithmetic} explains both readings, but does not identify which was intended here.',['serre1970arithmetic'],literal='not determinable',match='thematic only',verification='publisher metadata checked',confidence='medium',status='As of November 2026, the ambiguity is terminological and does not produce a new unsolved classification problem.')

item(226,'P000352','definition','Fiber products and their universal property',r'The object \(B\times_A C\) completes a commutative square and every compatible pair of maps to \(B,C\) factors through it uniquely.',r'For maps \(B\to A\leftarrow C\), a fiber product represents pairs \((X\to B,X\to C)\) whose composites to \(A\) agree. Its structure maps and unique factorization are part of the definition.',r'Compatibility with the maps to \(A\) is explicit; an arbitrary pair of maps does not suffice. This reprises item 1967-143.1.','E',r'This standard prerequisite is used in \citet[\S1]{geronimus1971topology} and the site axioms \citep[Tag 00VH]{stacks2026sites}.',['geronimus1971topology','stacks2026sites'],literal='correct')
item(226,'P000352','definition','Covering families define a Grothendieck pretopology',r'The conditions are composition of coverings, stability under base change, and \(U\to U\) being a cover; the last axiom number is overwritten.',r'A pretopology specifies covering families, contains identity covers, is stable under pullback, and is closed under composing a cover with covers of its members. Required pullbacks must exist; these families generate a Grothendieck topology by covering sieves.',r'The family axioms describe a pretopology. The overwritten numeral is immaterial. Related definitions occur in 1967-143.2 and 1968-151.1.','E',r'Geronimus uses this framework \citep[\S1]{geronimus1971topology}; precise modern family axioms are in \citet[Tag 00VH, Definition 7.6.2]{stacks2026sites}.',['geronimus1971topology','stacks2026sites'])
item(226,'P000352','definition','The sheaf axiom is an equalizer condition',r'A contravariant functor \(F:C\to K\) is followed by \(0\to F(A)\to\prod F(U_\alpha)\rightrightarrows\prod F(U_\alpha\times_AU_\beta)\).',r'For a set-valued presheaf, \(F(A)\) must be the equalizer of the restriction maps to overlaps for every cover. In an abelian target this is \(0\to F(A)\to\prod F(U_\alpha)\xrightarrow{d}\prod F(U_\alpha\times_AU_\beta)\), with \(d\) the difference of restrictions. General target categories need the stated limits.',r'Zero and exact-sequence notation cannot literally be imposed on an arbitrary category \(K\).','E',r'The matching condition is recorded by \citet[Tag 00VM, Definition 7.7.1]{stacks2026sites} and used by \citet[\S1]{geronimus1971topology}.',['stacks2026sites','geronimus1971topology'])
item(226,'P000353','construction','Čech cohomology and associated sheaves',r'For a cover \(\mathcal U\), one forms \(H(\mathcal U,F)\); a marked nontrivial theorem says that the preceding construction produces a sheaf.',r'For an abelian presheaf, overlap products give a Čech complex for each cover. The matching-family plus construction, applied twice, gives the associated sheaf. Čech cohomology of one cover need not equal derived sheaf cohomology without acyclicity hypotheses; a spectral sequence relates them.',r'The unspecified construction is matched cautiously with Geronimus\textquoteright s sheafification discussion. No claim that one cover computes all cohomology is inserted.','E',r'\citet[Propositions 1.3 and 1.6]{geronimus1971topology} supplies the associated-sheaf construction and cohomological spectral sequence.',['geronimus1971topology'],match='partial',confidence='medium')
item(226,'P000353','construction','Geronimus’s site of smooth group actions',r'Objects are \(G\)-manifolds and morphisms are called regular \(G\)-maps with surjective tangent maps.',r'For a Lie group \(G\), take smooth \(G\)-manifolds with all smooth equivariant maps as morphisms. A family is a cover when its members are equivariant submersions whose images jointly cover the target. Covers are stable under base change and composition.',r'Submersion is a condition on covering arrows, not every morphism.','E',r'The short announcement \citet[\S0]{geronimus1971lie}, received 28 August 1970 and published in the first 1971 issue, precedes this April exposition. The detailed construction is \citet[\S3.1]{geronimus1971topology}, received 22 September 1970 and published later in 1971.',['geronimus1971lie','geronimus1971topology'],literal='false as written')
item(226,'P000353','theorem','Finite-group representations as sheaves on the group-set site',r'For finite \(G\), take finite \(G\)-sets and vector spaces; a representation \(T\) gives tuples satisfying \(\xi_{g i}=T_g\xi_i\). All sheaves arise this way.',r'On finite left \(G\)-sets with jointly surjective equivariant covers, sheaves of vector spaces over a fixed field are equivalent to linear representations of \(G\). A module \(E\) gives \(F_E(X)=\operatorname{Map}_G(X,E)\); evaluation at the regular \(G\)-set recovers \(E\) and its action.',r'The topology and coefficient field are supplied. The five-point illustration does not restrict the equivalence to five-element sets.','E',r'Geronimus identifies this older finite/discrete-group construction and credits Artin in the introduction and \S2 \citep{geronimus1971topology}; \citet[Theorem 1]{geronimus1971lie} records its cohomological comparison.',['geronimus1971topology','geronimus1971lie'])
item(226,'P000353','construction','A Lie-group representation gives an equivariant-function sheaf',r'From \(X,T_g\) construct vector-valued functions \(\xi\), with \(T_g\xi(xg^{-1})=\xi(x)\). There are sheaves not obtained from representations.',r'For a continuous Banach representation \(E\) of a Lie group, smooth equivariant maps \(X\to E\) form a sheaf on the submersion site. Its value on \(G\) is the space \(E^\infty\) of smooth vectors. The finite-group equivalence does not justify an equivalence with all continuous Banach representations in the Lie-group case.',r'Left and right conventions are reconciled by equivariance. The wider non-equivalence claim depends on the category of representations, which the notes omit; it is not asserted for every generalized notion of representation.','E',r'\citet[\S7.1 and Proposition 7.3]{geronimus1971topology} gives the function sheaf and recovers the Gårding space. The comparison is announced in \citet[Theorem 3]{geronimus1971lie}.',['geronimus1971topology','geronimus1971lie'],match='partial',confidence='medium')
item(226,'P000353','theorem','Classifying-space and differentiable cohomology comparisons',r'Sometimes the construction gives cohomology of a topological space, sometimes cohomology as in Gelfand--Fuchs.',r'For the group-action site, a locally constant coefficient group \(A\) gives \(H^*(BG;A)\). For the smooth equivariant-function sheaf of a Banach representation, site cohomology agrees with the differentiable group cohomology denoted \(H_{\rm alg}^*(G;E^\infty)\) by Geronimus.',r'These use distinct coefficient sheaves; no general identification of Lie-algebra and classifying-space cohomology is inserted.','E',r'The comparisons appear in \citet[Theorems 2 and 3]{geronimus1971lie}; the detailed classifying-space statement is \citet[Proposition 4.3]{geronimus1971topology}.',['geronimus1971lie','geronimus1971topology'],match='partial')
item(226,'P000353','remark','Representation theory and the classification of particles',r'Elementary-particle theory is incomplete because not all representations are known; spinors and electrons are mentioned.',r'This motivates connecting particle descriptions with representation theory. No symmetry group, representation class, or mathematical completeness assertion is specified.',r'The remark is preserved without replacing it by a claim that physical theories are determined solely by a list of representations.','F',r'The surrounding Geronimus construction supplies context \citep{geronimus1971topology}, but no precise mathematical claim or publication match follows.',['geronimus1971topology'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',status='As of November 2026, this is a research motivation, not a formulated mathematical problem.')

item(227,'P000354','definition','The elliptic curve and the handwritten cubic exponent',r'The scan reads \(y^3=x^3-g_1x-g_2\), with rational coefficients, and calls the curve elliptic.',r'A smooth projective genus-one curve over \(\mathbb Q\) with a rational point is an elliptic curve. The written homogeneous cubic \(Y^3=X^3-g_1XZ^2-g_2Z^3\), if smooth, has the rational point \([1:1:0]\), so it can indeed define an elliptic curve. The familiar short Weierstrass equation instead has \(y^2\).',r'The exponent three is confirmed by the scan and is not automatically a mathematical error. Smoothness is missing; subsequent reduction is interpreted after passage to a minimal Weierstrass equation. No silent replacement of three by two is made.','E',r'The Weierstrass-model conventions used for the subsequent arithmetic are in \citet[\S3.1]{cremona1997algorithms}. The intended equation is not determined beyond the surviving cubic.',['cremona1997algorithms'],match='partial',confidence='medium')
item(227,'P000354','construction','The congruence subgroup and compact modular curve',r'\(\Gamma_0(A)\) consists of matrices \(\left(\begin{smallmatrix}\alpha&\beta\\A\gamma&\delta\end{smallmatrix}\right)\), but its displayed action is \((\alpha z+A\gamma)/(\beta z+\delta)\).',r'For \(N\ge1\), \(\Gamma_0(N)=\{\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)\in\mathrm{SL}_2(\mathbb Z):N\mid c\}\) acts on \(\mathfrak H\) by \(z\mapsto(az+b)/(cz+d)\). Adding cusps gives the compact modular curve \(X_0(N)\).',r'The off-diagonal entries are interchanged in the notebook action. The transposed subgroup is conjugate, but the written matrix and action cannot both be kept under the standard convention. A fundamental region is not yet the compact curve.','E',r'The conventions are in \citet[\S\S2.1.1 and 2.15.1]{cremona1997algorithms}.',['cremona1997algorithms'],literal='false as written')
item(227,'P000354-P000355','conjecture','Modularity of every elliptic curve over the rationals',r'The Weil conjecture asserts a nontrivial analytic map \(X_A\to T\), with level \(A\) chosen as the conductor.',r'For every elliptic curve \(E/\mathbb Q\) of conductor \(N\), there is a normalized weight-two cuspidal newform on \(\Gamma_0(N)\) with \(L(E,s)=L(f,s)\). Equivalently, \(E\) admits a nonconstant modular parametrization \(X_0(N)\to E\) over \(\mathbb Q\).',r'Nonconstant, compactification at cusps, and the arithmetic field are explicit. This is elliptic-curve modularity, not the Weil conjectures for varieties over finite fields.','B',r'\citet[Theorem A and Introduction]{breuilconraddiamondtaylor2001modularity} proves modularity for all \(E/\mathbb Q\), completing the earlier semistable case. The integral parametrization is explained in \citet[\S\S2.6 and 2.15.1]{cremona1997algorithms}.',['breuilconraddiamondtaylor2001modularity','cremona1997algorithms'],problem='GP-1970-53',status='As of November 2026, solved by the modularity theorem; the full result was published in 2001.')
problem('GP-1970-53','Modular parametrization of a rational elliptic curve',r'For every elliptic curve \(E/\mathbb Q\) of conductor \(N\), construct a nonconstant morphism \(X_0(N)\to E\) over \(\mathbb Q\), equivalently identify its \(L\)-series with a weight-two newform.',['1970-227.3','1970-227.7','1970-227.8'],r'As of November 2026, solved: the full modularity theorem was proved by Breuil, Conrad, Diamond, and Taylor and published in 2001.',['breuilconraddiamondtaylor2001modularity','cremona1997algorithms'])
item(227,'P000354','claim','There are not finitely many unrestricted maps to a torus',r'A parenthesis says there are finitely many maps from every curve to a torus.',r'Without normalization this is false: translating a map by arbitrary target points gives infinitely many maps, even constant ones. If a nonconstant \(\varphi:C\to E\) exists, the maps \([m]\circ\varphi\), \(m\ge1\), remain distinct after fixing a base point sent to zero, since their degrees grow as \(m^2\deg\varphi\).',r'The intended restriction, perhaps fixed degree or a quotient by operations on the target, is unspecified. These counterexamples do not require identifying that intention.','F',r'The modular-parametrization construction \citep[\S2.15.1]{cremona1997algorithms} supplies examples of maps but does not support the unrestricted finiteness sentence.',['cremona1997algorithms'],literal='false as written',match='none found',verification='indirect',confidence='high',status='As of November 2026, the literal assertion is false; an intended historical finiteness theorem cannot be uniquely recovered.')
item(227,'P000354-P000355','definition','Reduction types and conductor exponents',r'For \(p\ne2,3\), smooth reduction contributes \(A_p=1\), distinct tangents give \(A_p=p\), and coincident tangents give \(A_p=p^2\); \(A=\prod A_p\).',r'For a minimal integral Weierstrass model over \(\mathbb Q_p\), good, multiplicative, and additive reduction have conductor exponents \(0,1,2\), respectively, for \(p\ge5\). Multiplicative reduction is split or nonsplit according to whether its tangent directions are defined over \(\mathbb F_p\). At \(p=2,3\), wild ramification can increase the additive exponent.',r'Minimality is essential. The global conductor includes exceptional primes, whose exponents the simple table does not determine. Split/nonsplit replaces real/imaginary over finite fields.','E',r'Reduction and conductor computations are in \citet[\S\S3.1--3.2]{cremona1997algorithms}, including Tate\textquoteright s algorithm at exceptional primes. This modern source documents prior background, not a work claimed to precede the talk.',['cremona1997algorithms'])
item(227,'P000355','construction','Local Euler factors of the elliptic-curve L-function',r'At good primes \(L_p(s)=(1-c_pp^{-s}+p^{1-2s})^{-1}\), with \(\#E(\mathbb F_p)=1-c_p+p\); multiplicative reduction gives signs \(\pm1\), and additive reduction the factor one.',r'At a good prime set \(a_p=p+1-\#E(\mathbb F_p)\), so \(L_p(E,s)=(1-a_pp^{-s}+p^{1-2s})^{-1}\). Split and nonsplit multiplicative primes give \((1-p^{-s})^{-1}\) and \((1+p^{-s})^{-1}\); additive primes give one. Their product defines \(L(E,s)\) in its initial half-plane of absolute convergence.',r'The factors use a minimal model and the correct reduction type. This elliptic \(L\)-function is not the full zeta function of a curve.','E',r'The local data and matching coefficients are in \citet[\S\S2.6 and 3.9]{cremona1997algorithms}; equality with the modular \(L\)-series follows from \citet{breuilconraddiamondtaylor2001modularity}.',['cremona1997algorithms','breuilconraddiamondtaylor2001modularity'])
item(227,'P000355','construction','From Dirichlet coefficients to a weight-two modular form',r'Expand \(\zeta(s)=\sum c_n/n_s\), then write \(\omega(z)=\sum c_ne^{inz}\).',r'Write \(L(E,s)=\sum_{n\ge1}a_nn^{-s}\). Modularity states that \(f(z)=\sum_{n\ge1}a_ne^{2\pi inz}\) is the normalized weight-two newform of level \(N(E)\). Its invariant differential is \(2\pi i f(z)\,dz\).',r'The visible \(n_s\) is mathematically emended to \(n^s\). The factor \(2\pi\) uses the standard unit-period coordinate; \(e^{inz}\) requires rescaling coordinate and action. Forming the Fourier series does not prove modularity.','B',r'The newform assertion is part of \citet[Introduction, Theorem A]{breuilconraddiamondtaylor2001modularity}; normalization is in \citet[\S2.6]{cremona1997algorithms}.',['breuilconraddiamondtaylor2001modularity','cremona1997algorithms'],literal='false as written',problem='GP-1970-53')
item(227,'P000355','method','Integrating the modular differential gives the parametrization',r'\(\int\omega(z)\,dz\) is the sought map, and \(\int_z^{gz}\omega(z)\,dz\) should lie in a lattice for \(g\in\Gamma_0(A)\).',r'The rational-coefficient newform attached to \(E\) has a rank-two period lattice \(\Lambda_f\). Integration from a base cusp defines \(X_0(N)\to\mathbb C/\Lambda_f\). This target is isogenous to \(E\); composition with an appropriate isogeny gives a parametrization of \(E\). Under \(\Gamma_0(N)\), the integral changes by a period.',r'The base point, invariant differential, quotient, and possible isogeny are supplied. The assertion does not hold for an arbitrary integer-coefficient Fourier series.','B',r'\citet[\S2.15.1]{cremona1997algorithms} gives the period construction. Its applicability to every rational elliptic curve follows from \citet{breuilconraddiamondtaylor2001modularity}.',['cremona1997algorithms','breuilconraddiamondtaylor2001modularity'],problem='GP-1970-53')

item(228,'P000356','definition','A positive compatible complex structure and a principal lattice',r'\(B\) is nondegenerate skew and integral on \(L\); \(J^2=-1\), \(J^TBJ=B\), \(BJ>0\). The Hermitian form is \(H(z,w)=B(z,Jw)+iB(z,w)\).',r'Let \((V,B)\) be real symplectic of dimension \(2N\), \(L\) a full integral lattice, and \(J\) a compatible complex structure with \(B(v,Jv)>0\) for nonzero \(v\). Then \(H\) is positive Hermitian, conjugate-linear in its first slot. Principality means \(B:L\to L^*\) is unimodular.',r'Volume one uses the symplectic normalization. Compatibility alone does not imply positivity; this is a separate condition, and nondegeneracy makes nonnegative positivity strict.','E',r'These conventions are in \citet[\S\S1.1 and 1.2(c)]{cartier1968theta}; the notebook also refers to Cartier\textquoteright s earlier exposition \citep{cartier1966theta}.',['cartier1968theta','cartier1966theta'])
item(228,'P000356','construction','Quadratic refinements of the integral symplectic pairing',r'\(F(\alpha+\beta)=F(\alpha)+F(\beta)+B(\alpha,\beta)\pmod2\); adding linear forms gives \(4^N\) solutions.',r'Refinements of the alternating pairing on \(L/2L\) form an affine space over \(\operatorname{Hom}(L,\mathbb F_2)\). In a symplectic basis, \(F(m,n)=m\cdot n+\varepsilon\cdot m+\widetilde\varepsilon\cdot n\), with \(\varepsilon,\widetilde\varepsilon\in\mathbb F_2^N\); there are \(2^{2N}=4^N\) choices.',r'Only values modulo two matter; integer lifts give the same signs. The extra prime on one source coefficient does not affect the count.','E',r'\citet[\S1.1]{cartier1968theta} develops this description.',['cartier1968theta'],literal='correct')
item(228,'P000356','theorem','Theta automorphy and its one-dimensional solution space',r'Entire \(\Theta\) satisfies \(\Theta(z+\alpha)=(-1)^{F(\alpha)}e^{\pi H(\alpha,\alpha)/2+\pi H(\alpha,z)}\Theta(z)\), uniquely up to a constant for a principal lattice.',r'For the positive compatible principally polarized data in 1970-228.1--2, the entire functions satisfying this law form a one-dimensional vector space. Nonzero solutions are unique up to nonzero scalar.',r'Positivity and principality are essential. Linearity of \(H\) in its second slot makes the factor holomorphic in \(z\); no conjugate of \(z\) should be inserted.','E',r'The theta realization appears in \citet[\S1.3]{cartier1968theta} and is used in \citet[\S5]{perelomov1971completeness}.',['cartier1968theta','perelomov1971completeness'],literal='correct')
item(228,'P000356','remark','The idempotent anecdote attributed to Pauli',r'Gelfand writes \(P^2=P\), \(\lambda^2=\lambda\), then \(\lambda=0,+1,-1\), with \(-1\) discarded for physical reasons.',r'Over \(\mathbb R\) or \(\mathbb C\), an eigenvalue of an idempotent satisfies \(\lambda(\lambda-1)=0\), hence is zero or one. Minus one is excluded algebraically.',r'This is an anecdote or joke, not silently changed into a different operator equation. No Pauli volume or passage is identified.','F',r'No precise Pauli publication match was recovered from the book-and-idempotent wording. The correction follows directly from the written polynomial.',[],literal='false as written',match='none found',verification='unresolved lead',confidence='high',speaker='I. M. Gelfand',status='As of November 2026, the algebraic statement is settled; the anecdote\textquoteright s target is unidentified.')
item(228,'P000357-P000358','construction','Coherent states, the Bargmann space, and its evaluation kernel',r'\(a|\alpha\rangle=\alpha|\alpha\rangle\), labels fill \(\mathbb C\), and \(|\langle\alpha|\beta\rangle|^2=e^{-|\alpha-\beta|^2}\). Orthogonality means an entire function vanishes at the chosen labels.',r'In \(\mathcal F^2=\{f\text{ entire}:\pi^{-1}\int_{\mathbb C}|f(z)|^2e^{-|z|^2}\,dA<\infty\}\), normalized kernels are \(k_\alpha(z)=e^{-|\alpha|^2/2+\bar\alpha z}\). With the inner product linear in the second slot, \(\langle k_\alpha,f\rangle=e^{-|\alpha|^2/2}f(\alpha)\). Their span is dense exactly when the labels form a uniqueness set. A finite accumulation point of distinct labels suffices by the identity theorem.',r'The conjugation convention and positive area measure are fixed. The Gaussian overlap kernel is positive definite, also by multiplying a Gram kernel entrywise with its conjugate; the marginal Neumann--Schoenberg reference supplies no distinct new theorem.','E',r'The reduction and coherent-state formulas appear in \citet[\S\S1--2 and 4]{perelomov1971completeness}, published in February 1971.',['perelomov1971completeness'],problem='GP-1970-54')
item(228,'P000357','theorem','The critical area and the exact deletion threshold',r'Cell area greater than \(\pi\) gives incompleteness, smaller area overcompleteness. At area \(\pi\), deleting one state leaves completeness, deleting two destroys it.',r'For a full lattice \(\Lambda\subset\mathbb C\) with fundamental area \(S\), coherent states are incomplete for \(S>\pi\), and complete after every finite deletion for \(S<\pi\). At \(S=\pi\), the full system and every one-point deletion are complete, whereas every two-point deletion is incomplete.',r'The abbreviation means deleting points in context, not selecting only one or two. The critical excess-one statement is more precise than a density threshold.','E',r'\citet[Assertion 1, \S4]{perelomov1971completeness} proves these exact alternatives. Received 20 August 1970, it appeared in February 1971; its 2002 arXiv date is a later archival posting.',['perelomov1971completeness'],literal='correct',problem='GP-1970-54')
item(228,'P000357-P000358','theorem','Perelomov’s critical-lattice theta identity',r'For \(\lambda_{mn}=m\omega_1+n\omega_2\) at area \(\pi\), \(\sum_{m,n}(-1)^{mn+m+n}e^{-|\lambda_{mn}|^2/2+\lambda_{mn}z}=0\); the notes call this one relation.',r'If \(|\operatorname{Im}(\overline{\omega_1}\omega_2)|=\pi\), this series converges absolutely and uniformly on compact subsets of \(\mathbb C\) and vanishes identically. It is an identity of entire functions. Its coefficient signs are not square summable, so it is not automatically a norm-convergent dependence in the coherent-state Hilbert space.',r'Reflecting the lattice reconciles kernel conjugations. The informal one-relation statement concerns the completeness defect, not the kernel of an unspecified bounded synthesis operator.','E',r'This is \citet[Eq.~(39) and the following theta argument]{perelomov1971completeness}. Whether it follows from a particular Jacobi identity concerns the proof route, not an unresolved identity.',['perelomov1971completeness'],problem='GP-1970-54')
item(228,'P000357-P000358','question','Can an orthonormal basis have a uniformly bounded uncertainty product?',r'Von Neumann\textquoteright s question asks whether \(\delta_x\delta_p\) stays bounded after orthogonalizing the critical coherent lattice. The notes then ask the general question for an orthogonal system; Gelfand thinks a positive answer unlikely.',r'For unit vectors \(e_j\in L^2(\mathbb R)\), use centered standard deviations of position and Fourier momentum. There exists an orthonormal basis with \(\sup_j\Delta_x(e_j)\Delta_p(e_j)<\infty\). There even exists one with both centered second moments uniformly bounded. For a regular single-window Gabor basis, simultaneous finite second moments are impossible.',r'The scan expressly asks about the product. General basis existence, a particular Gram--Schmidt ordering of coherent states, and preservation of a fixed Gabor lattice are different formulations.','B',r'Meyer\textquoteright s Schwartz wavelets give bounded product \citep[\S2, Theorem 1]{meyer1987uncertainty}, lectured February 1986 and published 1987. Bourgain\textquoteright s November 1986 preprint, published 1988, gives separate bounds \citep[Theorem, preprint p.~3]{bourgain1988uncertainty}. The distinction from Balian--Low and higher-moment obstructions appears in \citet[Eq.~(1.1), Theorem 1.1, pp.~115--116]{grochenigmalinnikova2013localization}.',['meyer1987uncertainty','bourgain1988uncertainty','grochenigmalinnikova2013localization'],problem='GP-1970-59',status='As of November 2026, the unrestricted basis question has a positive established answer. An unspecified orthogonalization algorithm is not settled by this existence theorem.',development='annotated')
problem('GP-1970-59','Uniform centered uncertainty for an orthonormal basis',r'Does \(L^2(\mathbb R)\) admit an orthonormal basis \((e_j)\) with \(\sup_j\Delta_x(e_j)\Delta_p(e_j)<\infty\)? The notebook also mentions an unspecified orthogonalization of a critical coherent lattice.',['1970-228.8'],r'As of November 2026, yes for general bases: Meyer wavelets give the product bound and Bourgain gives separate uniform centered second-moment bounds. Balian--Low prohibits the corresponding regular single-window Gabor basis. No assertion covers every ordering or an unspecified Gram--Schmidt procedure.',['meyer1987uncertainty','bourgain1988uncertainty','grochenigmalinnikova2013localization'])
item(228,'P000358-P000359','construction','Odd theta characteristics give the higher-dimensional identities',r'The count is \(2^{N-1}(2^N-1)\), but the closing paragraph says half the \(4^N\) choices vanish. A Gaussian theta series equals \(c\Theta\).',r'For a principal lattice, odd refinements number \(2^{N-1}(2^N-1)\), and even ones \(2^{N-1}(2^N+1)\). The Gaussian Poincaré series \(\sum_{\alpha\in L}(-1)^{F(\alpha)}e^{-\pi H(\alpha,\alpha)/2+\pi H(\alpha,z)}\) has the theta automorphy and is a scalar multiple of its theta function. It is even in \(z\); for an odd characteristic the theta function is odd, forcing the scalar to vanish.',r'The word half is false even for \(N=1\). Parity proves the odd-characteristic identities but does not exclude extra vanishing of even theta constants on special higher-dimensional tori.','E',r'The refinement and parity framework appears in \citet[\S\S1.1 and 1.3]{cartier1968theta}; the theta-series argument is used in \citet[\S5]{perelomov1971completeness}.',['cartier1968theta','perelomov1971completeness'],literal='false as written')
item(228,'P000358-P000359','construction','Weyl operators and the central lattice cocycle',r'Heisenberg matrices are followed by \(D=e^{i\varphi}e^{i(\alpha^*a-\alpha a^*)}\). The subgroup uses lattice \(\alpha+i\beta\) and central coordinate \(k\pi\).',r'With \([a,a^\dagger]=1\), unitary displacement operators are \(D(\alpha)=\exp(\alpha a^\dagger-\bar\alpha a)\), up to replacing \(\alpha\) by \(-\alpha\). Multiplication carries the symplectic phase cocycle. A lattice lift must incorporate it, equivalently a quadratic refinement; restricting a raw triangular central entry to \(\pi\mathbb Z\) need not give a subgroup for an arbitrary plane lattice.',r'The extra inner \(i\) turns a skew-adjoint exponent into a self-adjoint one and does not give the claimed unitary operator. Triangular and symmetric group coordinates have different central cocycles.','E',r'The displacement and cocycle formulas are in \citet[\S5, Eqs.~(60)--(71)]{perelomov1971completeness}; the lattice lift is described by \citet[\S1.2]{cartier1968theta}.',['perelomov1971completeness','cartier1968theta'],literal='false as written')
item(228,'P000359','theorem','The lattice model is irreducible after fixing the central character',r'Induction from the signs \((-1)^{mn+m+n}\) on a discrete subgroup is said to give an irreducible representation.',r'For the Heisenberg group with circle center \(T\), a principal lattice has a compatible lift \(\Gamma\). Inducing from \(T\Gamma\) with the prescribed nontrivial central character gives the irreducible lattice realization of the Schrödinger representation. Induction from a discrete subgroup without fixing the full central character is not generally irreducible.',r'The inducing subgroup and character must include the center. Principality supplies multiplicity one.','E',r'The exact formulation is \citet[\S1.2(b), pp.~420--421]{cartier1968theta}; the notebook abbreviates the essential central-character condition.',['cartier1968theta'])
item(228,'P000357-P000358','question','Completeness for an arbitrary sequence of coherent states',r'\ru{Для каких послед.} \(\lambda_n\) \ru{полная система?} The proof asks whether a nonzero Fock function can vanish at all labels.',r'For a locally finite set \(\Lambda\subset\mathbb C\), characterize when no nonzero \(f\in\mathcal F^2\) vanishes on \(\Lambda\). Equivalently, characterize completeness of its coherent kernels. This is uniqueness, not the stronger stable sampling property.',r'Distinct labels and local finiteness isolate the nontrivial question. Finite accumulation is covered by 1970-228.5; area alone suffices only in the lattice case.','C',r'A verified partial criterion is \citet[Definition 1.1, Theorem 1.2 and Remark 1.3]{mitkovskiwick2013uniqueness}, circulated 3 June 2013. In normalization \(e^{-\pi|z|^2}\), a separated \(d\)-regular perturbation \(\gamma_{mn}\) of \((m+in)/d\), with \(|m+in-d\gamma_{mn}|\le\phi(|m+in|)\), \(\phi(t)/t\) nonincreasing and \(\int_1^\infty\phi(t)t^{-2}dt<\infty\), is unique for \(d>1\), nonunique for \(d<1\); \(d=1\) admits both. A September 2026 zero-set preprint is an unverified lead \citep{houma2026zeros}.',['perelomov1971completeness','mitkovskiwick2013uniqueness','houma2026zeros'],literal='correct',match='partial',confidence='medium',problem='GP-1970-54',status='As of November 2026, the lattice and stated perturbative cases are verified. Those results leave arbitrary irregular sets untreated; this audit has not established whether a complete modern characterization is available. The 2026 lead could not be opened, so no global claim of continued openness or resolution is made.',worth='A precise critical-density extension could merit work, but further development should first check the inaccessible 2026 lead and other recent classification results; no Stage 2 novelty claim is warranted here.')
problem('GP-1970-54','Which sequences of coherent states are complete?',r'Characterize sets \(\Lambda\subset\mathbb C\) for which the normalized coherent states span the Bargmann--Fock space densely, equivalently its uniqueness sets.',['1970-228.5','1970-228.6','1970-228.7','1970-228.12'],r'As of November 2026, Perelomov\textquoteright s lattice criterion and the stated Mitkovski--Wick perturbation criteria are verified. An unrestricted characterization is not established by this audit; a September 2026 zero-set preprint remains an unverified lead. Sampling density theorems alone do not answer the exact question.',['perelomov1971completeness','mitkovskiwick2013uniqueness','houma2026zeros'])
item(228,'P000359','remark','A proposed group-orbit generalization',r'An intervention provisionally attributed to Kazhdan starts with \(T:G\to U(H)\), \(h_0\in H\), and discrete \(\Gamma\subset G\). For a reasonable subgroup, \(\{T(\gamma)h_0\}\) should be complete with finitely many relations.',r'No group or representation class, cyclicity assumption, meaning of reasonable, or permitted topology and coefficients for relations is given. Completeness already fails if \(h_0\) lies in a proper invariant subspace.',r'The abbreviation after \(G\) is not expanded into a theorem about all semisimple groups. The coherent-state prototype does not determine the missing quantifiers.','F',r'The Heisenberg model \citep[\S1.2]{cartier1968theta} and exact coherent-lattice result \citep{perelomov1971completeness} identify the prototype. No exact general-group theorem follows from this intervention.',['cartier1968theta','perelomov1971completeness'],literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',speaker='D. A. Kazhdan (provisional attribution)',status='As of November 2026, the generalization is too underspecified for a definite problem-index entry; no unsolved universal theorem is asserted.')

item(228,'P000357','definition','Finite-deletion overcompleteness',r'Overcomplete means that throwing away any finite number of vectors leaves a complete system.',r'A total family in a Hilbert space has the finite-deletion property if the complement of every finite subset still has dense linear span. This is stronger than some uses of overcomplete meaning merely redundant or nonminimal.',r'The notebook explicitly fixes its convention; no uniform frame bounds are implied.','E',r'The lattice alternatives in \citet[Assertion 1]{perelomov1971completeness} distinguish this property from critical excess one.',['perelomov1971completeness'],literal='correct',problem='GP-1970-54')
item(228,'P000357','claim','The unnormalized complex-shift Gaussian series needs correction',r'After the entire-function identity the notes write an alternative \(\sum_{m,n}(-1)^{mn+m+n}e^{-(x-\lambda_{mn})^2/2}\), with complex lattice labels.',r'The literal complex-shift series need not even have terms tending to zero. For normalized oscillator coherent states write \(\alpha=(q+ip)/\sqrt2\) and \(\psi_\alpha(x)=\pi^{-1/4}\exp(-(x-q)^2/2+ip(x-q/2))\). The normalization and phase are essential when transporting a Bargmann identity to the position representation.',r'The second display is not justified by substituting complex centers into real normalized Gaussians. Its interpretation as a formal vector identity also needs the convergence qualifications in 1970-228.7.','E',r'The normalized displacement representation in \citet[\S5, Eqs.~(60)--(71)]{perelomov1971completeness} supplies the correct coherent states. For a nonreal lattice direction with imaginary part larger in absolute value than its real part, the notebook terms grow along its multiples, directly disproving ordinary convergence.',['perelomov1971completeness'],literal='false as written',match='partial')

